new Supplier<Integer>() {

    @Override
    public Integer get() {
        String rawValue = SystemReader.getInstance().getProperty(MAX_REDIRECT_SYSTEM_PROPERTY);
        Integer value = Integer.valueOf(DEFAULT_MAX_REDIRECTS);
        if (rawValue != null) {
            try {
                value = Integer.valueOf(Integer.parseUnsignedInt(rawValue));
            } catch (NumberFormatException e) {
                LOG.warn(MessageFormat.format(JGitText.get().invalidSystemProperty, MAX_REDIRECT_SYSTEM_PROPERTY, rawValue, value));
            }
        }
        return value;
    }
}.get()

new //$NON-NLS-1$
Thread(//$NON-NLS-1$
processors, //$NON-NLS-1$
"Git-Daemon-Client " + peer.toString()) {

    @Override
    public void run() {
        try {
            dc.execute(s);
        } catch (ServiceNotEnabledException e) {
            // Ignored. Client cannot use this repository.
        } catch (ServiceNotAuthorizedException e) {
            // Ignored. Client cannot use this repository.
        } catch (IOException e) {
            // Ignore unexpected IO exceptions from clients
        } finally {
            try {
                s.getInputStream().close();
            } catch (IOException e) {
                // Ignore close exceptions
            }
            try {
                s.getOutputStream().close();
            } catch (IOException e) {
                // Ignore close exceptions
            }
        }
    }
}

